/**
 * Service Worker Template
 *
 * Generated by scripts/build-offline.mjs at build time. The build script
 * injects the current BUILD_ID as CACHE_VERSION so that every deployment
 * produces a new set of caches, guaranteeing that users receive fresh
 * content after an update (old caches are purged on activate).
 *
 * The generated output is written to public/sw.js and is also copied to
 * the static export directory (out/) if present.
 */

const CACHE_VERSION = "ZJTPt-m4SZuLL_WjMBx2e";
const STATIC_CACHE = `azadbalushi-static-${CACHE_VERSION}`;
const PAGE_CACHE = `azadbalushi-pages-${CACHE_VERSION}`;
const IMAGE_CACHE = `azadbalushi-images-${CACHE_VERSION}`;
const CACHE_PREFIX = 'azadbalushi-';
const VALID_CACHES = [STATIC_CACHE, PAGE_CACHE, IMAGE_CACHE];

const IMAGE_CACHE_MAX_ENTRIES = 40;

const PRECACHE_URLS = [
  '/offline.html',
  '/site.webmanifest',
  '/favicon.ico',
  '/icon-192.png',
];

// ---------------------------------------------------------------------------
// Install — precache minimal shell, then activate immediately
// ---------------------------------------------------------------------------
self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(STATIC_CACHE);
      await Promise.all(
        PRECACHE_URLS.map((url) =>
          cache.add(new Request(url, { cache: 'reload' })).catch(() => {}),
        ),
      );
      await self.skipWaiting();
    })(),
  );
});

// ---------------------------------------------------------------------------
// Activate — purge old caches, claim clients
// ---------------------------------------------------------------------------
self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((key) => key.startsWith(CACHE_PREFIX) && !VALID_CACHES.includes(key))
          .map((key) => caches.delete(key)),
      );
      await self.clients.claim();
    })(),
  );
});

// ---------------------------------------------------------------------------
// Message — allow page to trigger immediate activation of a waiting SW
// ---------------------------------------------------------------------------
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

// ---------------------------------------------------------------------------
// Fetch — route by request type
// ---------------------------------------------------------------------------
self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);

  if (url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(networkFirstNavigation(request));
    return;
  }

  if (url.pathname.startsWith('/_next/static/')) {
    event.respondWith(cacheFirst(request, STATIC_CACHE));
    return;
  }

  if (request.destination === 'image') {
    event.respondWith(staleWhileRevalidate(request, IMAGE_CACHE, IMAGE_CACHE_MAX_ENTRIES));
    return;
  }

  if (
    url.pathname === '/site.webmanifest' ||
    url.pathname === '/offline.html' ||
    url.pathname === '/favicon.ico' ||
    url.pathname === '/apple-touch-icon.png' ||
    /^\/icon-\d+\.png$/.test(url.pathname) ||
    /^\/icon-maskable-\d+\.png$/.test(url.pathname)
  ) {
    event.respondWith(cacheFirst(request, STATIC_CACHE));
    return;
  }

  if (
    request.destination === 'style' ||
    request.destination === 'script' ||
    request.destination === 'font'
  ) {
    event.respondWith(staleWhileRevalidate(request, STATIC_CACHE));
    return;
  }

  event.respondWith(staleWhileRevalidate(request, STATIC_CACHE));
});

// ---------------------------------------------------------------------------
// Strategy helpers
// ---------------------------------------------------------------------------

async function networkFirstNavigation(request) {
  const cache = await caches.open(PAGE_CACHE);
  try {
    const networkResponse = await fetch(request);
    if (networkResponse.ok && networkResponse.type === 'basic') {
      cache.put(request, networkResponse.clone()).catch(() => {});
    }
    return networkResponse;
  } catch (_err) {
    const cached = await cache.match(request);
    if (cached) return cached;
    const offlineCache = await caches.open(STATIC_CACHE);
    const offline = await offlineCache.match('/offline.html');
    if (offline) return offline;
    return new Response('You are offline.', {
      status: 503,
      headers: { 'Content-Type': 'text/html; charset=utf-8' },
    });
  }
}

async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  if (cached) return cached;
  const response = await fetch(request);
  if (response.ok) {
    cache.put(request, response.clone()).catch(() => {});
  }
  return response;
}

async function staleWhileRevalidate(request, cacheName, maxEntries) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);

  const networkPromise = fetch(request)
    .then((response) => {
      if (response.ok) {
        cache.put(request, response.clone()).catch(() => {});
        if (maxEntries) trimCache(cache, maxEntries).catch(() => {});
      }
      return response;
    })
    .catch(() => cached);

  return cached || networkPromise;
}

async function trimCache(cache, maxEntries) {
  const keys = await cache.keys();
  if (keys.length <= maxEntries) return;
  const toRemove = keys.slice(0, keys.length - maxEntries);
  await Promise.all(toRemove.map((key) => cache.delete(key)));
}
